async function readExcelFile(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=(e)=>{try{const data=new Uint8Array(e.target.result);const workbook=XLSX.read(data,{type:'array',cellDates:true});const sheet=workbook.Sheets[workbook.SheetNames[0]];resolve(XLSX.utils.sheet_to_json(sheet));}catch(err){reject(err);}};reader.onerror=()=>reject(new Error('Read failed'));reader.readAsArrayBuffer(file);});}
